(window.KOTOBA_HK=window.KOTOBA_HK||{})[32]={"n":32,"S":[{"id":"l32a","ti":[[["みにくい","みにくい"],["アヒル","アヒル"],["の","の"],["子","こ"]]],"tt":{"az":"Çirkin ördək balası","en":"The Ugly Duckling","ru":"Гадкий утёнок"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["ある","ある","ある(連体詞)"],["池","いけ"],["に","に"]],[["アヒル","アヒル"],["の","の"]],[["お母さん","おかあさん"],["が","が"]],[["いました","いました","いる",2],["。"],["ある日","あるひ"],["、"],["卵","たまご"],["から","から"]],[["六羽","ろくわ"],["の","の"]],[["子ども","こども"],["が","が"]],[["生まれました","うまれました","生まれる",2],["。"],["でも","でも"],["、"],["一羽","いちわ"],["だけ","だけ"]],[["大きくて","おおきくて","大きい",3],["、"],["灰色","はいいろ"],["でした","でした","です",9],["。"],["ほか","ほか"],["の","の"]],[["アヒルたち","アヒルたち"],["は","は"],["、"],["その","その"],["子","こ"],["を","を"],["「"],["みにくい","みにくい"],["子","こ"],["」"],["と","と"],["いう","いう","いう",5]],[["名前","なまえ"],["で","で","だ"]],[["呼びました","よびました","呼ぶ",2],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, bir gölməçədə ana ördək yaşayırdı. Bir gün yumurtalardan altı bala çıxdı. Amma onlardan biri böyük və boz rəngdə idi. Digər ördəklər ona «Çirkin bala» adını qoymuşdular.","en":"Once upon a time, a mother duck lived by a pond. One day, six ducklings hatched from their eggs. But one of them was big and gray. The other ducks called that little one Ugly Duckling.","ru":"Давным-давно у одного пруда жила мама-утка. Однажды из яиц вылупились шесть утят. Но один из них был большим и серым. Другие утки прозвали его «Гадким утёнком»."}},{"t":[[["みにくい","みにくい"],["子","こ"],["は","は"],["、"],["みんな","みんな"],["と","と"]],[["仲よく","なかよく"]],[["なる","なる"],["ため","ため"],["に","に"],["、"],["毎日","まいにち"]],[["がんばりました","がんばりました","がんばる",2],["。"],["みんな","みんな"],["と","と"]],[["同じ","おなじ"],["ように","ように","よう",8]],[["泳げる","およげる","泳げる",5],["ように","ように","よう",8],["、"],["何回","なんかい"],["も","も"]],[["練習","れんしゅう"],["しました","しました","する",2],["。"],["でも","でも"],["、"],["みんな","みんな"],["は","は"],["「"],["こっち","こっち"],["へ","へ"]],[["来ないで","こないで","来る",18],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["悲しかった","かなしかった","悲しい",0],["の","の"],["で","で","だ"],["、"],["ある","ある","ある(連体詞)"],["朝","あさ"],["、"],["池","いけ"],["を","を"]],[["出ていきました","でていきました","出る",25],["。"]]],"tr":{"az":"Çirkin bala hamı ilə dostlaşmaq üçün hər gün çox çalışırdı. Başqaları kimi üzə bilmək üçün dəfələrlə məşq edirdi. Amma hamı ona «Bura gəlmə» deyirdi. Çox kədərləndiyi üçün bir səhər gölməçədən çıxıb getdi.","en":"The ugly duckling tried hard every day to become friends with everyone. He practiced many times so that he could swim like the others. But they told him, “Don't come over here.” He was so sad that one morning he left the pond.","ru":"Гадкий утёнок каждый день старался подружиться со всеми. Он много раз тренировался, чтобы научиться плавать, как остальные. Но все говорили ему: «Не подходи сюда». Ему было очень грустно, поэтому однажды утром он ушёл с пруда."}},{"t":[[["森","もり"],["で","で","だ"],["、"],["みにくい","みにくい"],["子","こ"],["は","は"]],[["白い","しろい"],["鳥","とり"],["を","を"]],[["見ました","みました","見る",2],["。"],["白い","しろい"],["鳥","とり"],["は","は"]],[["空","そら"],["を","を"]],[["高く","たかく","高い"]],[["飛んでいました","とんでいました","飛ぶ",31],["。"],["「"],["あの","あの"],["鳥","とり"],["は","は"]],[["何","なん"],["と","と"],["いう","いう","いう",5]],[["鳥な","とりな","鳥",1],["ん","ん"],["だろう","だろう","だ"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["いつ","いつ"],["か","か"]],[["自分","じぶん"],["も","も"]],[["あんな","あんな"],["ふう","ふう"],["に","に","だ"]],[["飛べる","とべる","飛べる",5],["か","か"],["どう","どう"],["か","か"],["、"],["知りたく","しりたく","知る",30]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Meşədə çirkin bala ağ bir quş gördü. Ağ quş səmada çox yüksəklərdə uçurdu. O, «Görəsən, bu quşun adı nədir?» deyə düşündü. Bir gün özünün də onun kimi uça bilib-bilməyəcəyini bilmək istədi.","en":"In the forest, the ugly duckling saw a white bird. The white bird was flying high in the sky. He wondered, “What is that bird called?” He wanted to know whether he too could fly like that someday.","ru":"В лесу гадкий утёнок увидел белую птицу. Она летела высоко в небе. Он подумал: «Как же называется эта птица?» Ему захотелось узнать, сможет ли он когда-нибудь летать так же."}},{"t":[[["やがて","やがて"]],[["冬","ふゆ"],["に","に"]],[["なりました","なりました","なる",2],["。"],["雪","ゆき"],["の","の"]],[["せい","せい"],["で","で"],["、"],["食べ物","たべもの"],["が","が"]],[["なかなか","なかなか"]],[["見つかりませんでした","みつかりませんでした","見つかる",4],["。"],["ある","ある","ある(連体詞)"]],[["おじいさん","おじいさん"],["が","が"],["、"],["寒","さむ","寒い"],["そうな","そうな","そう",1]],[["子","こ"],["を","を"]],[["見つけて","みつけて","見つける",3],["、"],["家","いえ"],["へ","へ"]],[["連れてきました","つれてきました","連れる",23],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["春","はる"],["まで","まで"]],[["ここ","ここ"],["に","に"]],[["い","い"],["なさい","なさい","なさる",10],["」"],["と","と"]],[["優しく","やさしく","優しい"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Bir müddət sonra qış gəldi. Qar üzündən yemək tapmaq çox çətin idi. Bir qoca üşüyən balanı görüb evinə apardı. Qoca ona mehribanlıqla «Yaza qədər burada qal» dedi.","en":"Before long, winter arrived. Because of the snow, it was difficult to find food. An old man found the cold little bird and brought him home. The old man kindly said, “Stay here until spring.”","ru":"Вскоре наступила зима. Из-за снега найти еду было очень трудно. Один старик заметил замёрзшую птицу и принёс её домой. Он ласково сказал: «Оставайся здесь до весны»."}},{"t":[[["おじいさん","おじいさん"],["は","は"],["、"],["毎日","まいにち"]],[["みにくい","みにくい"],["子","こ"],["に","に"]],[["ご飯","ごはん"],["を","を"]],[["あげました","あげました","あげる",2],["。"],["元気","げんき"],["に","に","だ"]],[["なる","なる","なる",5],["ように","ように","よう",8],["、"],["暖かい","あたたかい"]],[["部屋","へや"],["で","で","だ"]],[["休ませました","やすませました","休む",16],["。"],["おじいさん","おじいさん"],["の","の"]],[["おかげ","おかげ"],["で","で","だ"],["、"],["子","こ"],["は","は"]],[["少し","すこし"],["ずつ","ずつ"]],[["大きく","おおきく","大きい"]],[["なってきました","なってきました","なる",23],["。"],["長い","ながい"]],[["冬","ふゆ"],["の","の"]],[["間","あいだ"],["、"],["窓","まど"],["から","から"]],[["外","そと"],["を","を"]],[["見る","みる","見る",5],["ように","ように","よう",8]],[["していました","していました","する",15],["。"]]],"tr":{"az":"Qoca hər gün balaya yemək verirdi. Sağalması üçün onu isti otaqda dincəldirdi. Qocanın sayəsində bala yavaş-yavaş böyüməyə başladı. Uzun qış boyunca o, pəncərədən bayıra baxmağı adət etmişdi.","en":"The old man fed the duckling every day. He let him rest in a warm room so that he would grow healthy. Thanks to the old man, the little bird gradually grew bigger. Throughout the long winter, he made a habit of looking outside through the window.","ru":"Старик каждый день кормил утёнка. Он давал ему отдыхать в тёплой комнате, чтобы тот окреп. Благодаря старику птенец постепенно рос. Всю долгую зиму он старался каждый день смотреть в окно."}},{"t":[[["春","はる"],["が","が"]],[["来る","くる","来る",5],["と","と"],["、"],["おじいさん","おじいさん"],["は","は"]],[["子","こ"],["に","に"],["「"],["池","いけ"],["へ","へ"]],[["行って","いって","行く",3]],[["ごらん","ごらん"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["子","こ"],["は","は"]],[["おじいさん","おじいさん"],["に","に"]],[["言われた","いわれた","言う",55],["とおり","とおり"],["に","に"],["、"],["池","いけ"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["池","いけ"],["に","に"],["は","は"],["、"],["前","まえ"],["に","に"]],[["見た","みた","見る",0]],[["白い","しろい"],["鳥","とり"],["が","が"]],[["いました","いました","いる",2],["。"],["白い","しろい"],["鳥","とり"],["は","は"],["「"],["いっしょ","いっしょ"],["に","に"]],[["泳ごう","およごう","泳ぐ",7],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["近く","ちかく"],["へ","へ"]],[["来ました","きました","来る",2],["。"]]],"tr":{"az":"Yaz gələndə qoca balaya «Gölməçəyə get, bir bax» dedi. Bala qocanın dediyi kimi gölməçəyə getdi. Orada əvvəllər gördüyü ağ quş var idi. Ağ quş «Gəl birlikdə üzək» deyib ona yaxınlaşdı.","en":"When spring came, the old man said, “Go and visit the pond.” The little bird went to the pond just as the old man had told him. There was the white bird he had seen before. “Let's swim together,” said the white bird, coming closer.","ru":"Когда пришла весна, старик сказал: «Сходи к пруду». Птенец отправился к пруду, как велел старик. Там была белая птица, которую он видел раньше. «Давай поплаваем вместе», – сказала она и подплыла ближе."}},{"t":[[["みにくい","みにくい"],["子","こ"],["は","は"],["「"],["ぼく","ぼく"],["は","は"]],[["みにくい","みにくい"],["ん","ん"],["です","です"],["」"],["と","と"]],[["小さな","ちいさな"]],[["声","こえ"],["で","で","だ"]],[["言いました","いいました","言う",2],["。"],["白い","しろい"],["鳥","とり"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["「"],["水","みず"],["を","を"]],[["見て","みて","見る",3]],[["ごらん","ごらん"],["」"],["と","と"]],[["頼みました","たのみました","頼む",2],["。"],["水","みず"],["を","を"]],[["見る","みる","見る",5],["と","と"],["、"],["そこ","そこ"],["に","に"],["は","は"]],[["美しい","うつくしい"]],[["白鳥","はくちょう"],["が","が"]],[["いました","いました","いる",2],["。"],["みにくい","みにくい"],["子","こ"],["は","は"],["、"],["自分","じぶん"],["が","が"]],[["白鳥","はくちょう"],["に","に"]],[["なった","なった","なる",0],["ん","ん"],["だ","だ","です"],["と","と"]],[["わかりました","わかりました","わかる",2],["。"]]],"tr":{"az":"Çirkin bala alçaq səslə «Mən çirkinəm axı» dedi. Ağ quş gülümsəyərək ondan «Suya bir bax» deyə xahiş etdi. Suya baxanda orada gözəl bir qu quşu gördü. Çirkin bala başa düşdü ki, özü də qu quşuna çevrilib.","en":"“But I'm ugly,” the little bird said quietly. The white bird smiled and asked him to look into the water. When he looked, he saw a beautiful swan. The ugly duckling realized that he himself had become a swan.","ru":"«Но ведь я некрасивый», – тихо сказал утёнок. Белая птица улыбнулась и попросила его посмотреть в воду. В воде он увидел прекрасного лебедя. Гадкий утёнок понял, что сам стал лебедем."}},{"t":[[["「"],["ぼく","ぼく"],["も","も"]],[["白鳥","しらとり"],["だった","だった","です",9],["ん","ん"],["です","です"],["ね","ね"],["！"],["」"],["と","と"]],[["子","こ"],["は","は"]],[["喜びました","よろこびました","喜ぶ",2],["。"],["もう","もう"]],[["一人","ひとり"],["で","で"]],[["泳がなくても","およがなくても","泳ぐ",37]],[["いい","いい"],["ん","ん"],["です","です"],["。"],["新しい","あたらしい"]],[["友だち","ともだち"],["と","と"]],[["空","そら"],["を","を"]],[["飛べる","とべる","飛べる",5],["ように","ように","よう",8],["も","も"]],[["なりました","なりました","なる",2],["。"],["その","その"],["日","ひ"],["から","から"],["、"],["白鳥","はくちょう"],["は","は"]],[["誰","だれ"],["か","か"],["を","を"]],[["見た","みた","見る",0],["目","め"],["だけ","だけ"],["で","で","だ"]],[["決めない","きめない","決める",19],["ように","ように","よう",8]],[["しました","しました","する",2],["。"]]],"tr":{"az":"«Deməli, mən də qu quşu imişəm!» deyə bala sevindi. Artıq tək üzmək məcburiyyətində deyildi. O, yeni dostları ilə səmada uçmağı da öyrəndi. Həmin gündən etibarən qu quşu heç kimi yalnız görünüşünə görə qiymətləndirməməyə qərar verdi.","en":"“So I was a swan all along!” he cried happily. He no longer had to swim alone. He also learned to fly through the sky with his new friends. From that day on, the swan made sure never to judge anyone only by their appearance.","ru":"«Значит, я тоже был лебедем!» – радостно воскликнул он. Теперь ему больше не нужно было плавать одному. Он также научился летать по небу со своими новыми друзьями. С того дня лебедь старался никогда не судить других только по внешности."}}]},{"id":"l32b","ti":[[["魔法","まほう"],["の","の"],["ほうき","ほうき"],["と","と"]],[["空","そら"],["の","の"],["手紙","てがみ"]]],"tt":{"az":"Sehrli süpürgə və göydən gələn məktub","en":"The Magic Broom and the Letter from the Sky","ru":"Волшебная метла и письмо с неба"},"P":[{"t":[[["むかし","むかし"],["、"],["山","やま"],["の","の"]],[["上","うえ"],["の","の"]],[["小さな","ちいさな"]],[["町","まち"],["に","に"],["、"],["ミオ","ミオ"],["と","と"],["いう","いう","いう",5]],[["女の子","おんなのこ"],["が","が"]],[["いました","いました","いる",2],["。"],["その","その"],["町","まち"],["で","で"],["は","は"],["、"],["魔法","まほう"],["の","の"]],[["ほうき","ほうき"],["で","で","だ"]],[["空","そら"],["を","を"]],[["飛ぶ","とぶ","飛ぶ",5]],[["人","ひと"],["が","が"]],[["いました","いました","いる",2],["。"],["ミオ","ミオ"],["も","も"]],[["空","そら"],["を","を"]],[["飛ぶ","とぶ","飛ぶ",5],["ため","ため"],["に","に"],["、"],["古い","ふるい"]],[["ほうき","ほうき"],["を","を"]],[["買いました","かいました","買う",2],["。"],["でも","でも"],["、"],["ほうき","ほうき"],["は","は"]],[["少し","すこし"],["も","も"]],[["動きませんでした","うごきませんでした","動く",4],["。"]]],"tr":{"az":"Bir zamanlar dağın başındakı kiçik şəhərdə Mio adlı bir qız yaşayırdı. Bu şəhərdə sehrli süpürgələrlə göydə uçan insanlar var idi. Mio da uçmaq üçün köhnə bir süpürgə aldı. Amma süpürgə heç tərpənmədi.","en":"Long ago, in a small town on a mountain, there lived a girl named Mio. In that town, some people flew through the sky on magic brooms. Mio bought an old broom so she could fly too. But the broom did not move at all.","ru":"Давным-давно в маленьком городке на горе жила девочка по имени Мио. В этом городке некоторые люди летали по небу на волшебных мётлах. Мио тоже купила старую метлу, чтобы научиться летать. Но метла совсем не двигалась."}},{"t":[[["ミオ","ミオ"],["は","は"]],[["飛べる","とべる","飛べる",5],["ように","ように","よう",8]],[["なる","なる"],["ため","ため"],["に","に"],["、"],["毎朝","まいあさ"]],[["練習","れんしゅう"],["しました","しました","する",2],["。"],["魔法","まほう"],["の","の"]],[["本","ほん"],["に","に"]],[["書いてある","かいてある","書く",95],["とおり","とおり"],["に","に"],["、"],["ほうき","ほうき"],["に","に"]],[["乗りました","のりました","乗る",2],["。"],["でも","でも"],["、"],["ほうき","ほうき"],["は","は"]],[["地面","じめん"],["の","の"]],[["上","うえ"],["を","を"]],[["走る","はしる","走る",5],["だけ","だけ"],["でした","でした","です",9],["。"],["「"],["どう","どう"],["して","して","する",3]],[["飛べない","とべない","飛べる",19],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"],["、"],["ミオ","ミオ"],["は","は"]],[["空","そら"],["に","に"]],[["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Mio uçmağı öyrənmək üçün hər səhər məşq edirdi. Sehr kitabında yazıldığı kimi süpürgəyə minirdi. Amma süpürgə yalnız yerin üstü ilə hərəkət edirdi. Mio göyə baxıb soruşurdu: «Niyə uça bilmirəm axı?»","en":"Mio practiced every morning so that she could learn to fly. She sat on the broom exactly as the magic book instructed. But the broom only ran along the ground. “Why can't I fly?” Mio asked the sky.","ru":"Мио тренировалась каждое утро, чтобы научиться летать. Она садилась на метлу точно так, как было написано в волшебной книге. Но метла только ездила по земле. «Почему же я не могу взлететь?» – спрашивала Мио у неба."}},{"t":[[["ある日","あるひ"],["、"],["小さな","ちいさな"]],[["青い","あおい"],["鳥","とり"],["が","が"]],[["窓","まど"],["から","から"]],[["入ってきました","はいってきました","入る",23],["。"],["鳥","とり"],["は","は"],["「"],["空","そら"],["の","の"]],[["学校","がっこう"],["」"],["と","と"],["いう","いう","いう",5]],[["場所","ばしょ"],["から","から"]],[["手紙","てがみ"],["を","を"]],[["持ってきました","もってきました","持つ",23],["。"],["手紙","てがみ"],["に","に"],["は","は"],["「"],["明日","あした"],["の","の"]],[["朝","あさ"],["、"],["東","ひがし"],["の","の"]],[["山","やま"],["へ","へ"]],[["来る","くる","来る",5],["ように","ように","よう",8],["」"],["と","と"]],[["書いてありました","かいてありました","書く",36],["。"],["ミオ","ミオ"],["は","は"]],[["本当","ほんとう"],["の","の"]],[["手紙","てがみ"],["か","か"],["どう","どう"],["か","か"],["、"],["何回","なんかい"],["も","も"]],[["調べました","しらべました","調べる",2],["。"]]],"tr":{"az":"Bir gün kiçik mavi quş pəncərədən içəri uçdu. Quş «Səma məktəbi» adlı yerdən məktub gətirmişdi. Məktubda «Sabah səhər şərqdəki dağa gəl» yazılmışdı. Mio məktubun həqiqi olub-olmadığını dəfələrlə yoxladı.","en":"One day, a small blue bird flew in through the window. It brought a letter from a place called the Sky School. The letter said, “Come to the eastern mountain tomorrow morning.” Mio checked many times whether the letter was real.","ru":"Однажды маленькая синяя птица влетела в окно. Она принесла письмо из места под названием «Небесная школа». В письме было написано: «Приходи завтра утром к восточной горе». Мио много раз проверяла, настоящее ли это письмо."}},{"t":[[["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["ミオ","ミオ"],["は","は"]],[["手紙","てがみ"],["の","の"],["とおり","とおり"],["に","に"]],[["山","やま"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["そこ","そこ"],["に","に"],["は","は"],["、"],["白い","しろい"]],[["髪","かみ"],["の","の"]],[["おばあさん","おばあさん"],["が","が"]],[["待っていました","まっていました","待つ",15],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["飛ぶ","とぶ","飛ぶ",5],["とき","とき"],["は","は"],["、"],["下","した"],["を","を"]],[["見ない","みない","見る",19],["ように","ように","よう",8],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["ミオ","ミオ"],["に","に"]],[["目","め"],["を","を"]],[["閉じる","とじる","閉じる",5],["ように","ように","よう",8]],[["頼みました","たのみました","頼む",2],["。"]]],"tr":{"az":"Ertəsi səhər Mio məktubda yazıldığı kimi dağa getdi. Orada ağ saçlı bir nənə onu gözləyirdi. Nənə «Uçanda aşağı baxma» dedi. Sonra Miodan gözlərini yummağı xahiş etdi.","en":"The next morning, Mio went to the mountain as the letter instructed. A white-haired old woman was waiting there. “When you fly, try not to look down,” the old woman said. Then she asked Mio to close her eyes.","ru":"На следующее утро Мио отправилась к горе, как было написано в письме. Там её ждала седовласая старушка. «Когда будешь летать, старайся не смотреть вниз», – сказала старушка. Затем она попросила Мио закрыть глаза."}},{"t":[[["ミオ","ミオ"],["は","は"]],[["怖かった","こわかった","怖い",0],["の","の"],["で","で","だ"],["、"],["少し","すこし"]],[["震えました","ふるえました","震える",2],["。"],["でも","でも"],["、"],["おばあさん","おばあさん"],["の","の"]],[["言葉","ことば"],["の","の"]],[["おかげ","おかげ"],["で","で","だ"],["、"],["勇気","ゆうき"],["が","が"]],[["出てきました","でてきました","出る",23],["。"],["ミオ","ミオ"],["が","が"],["「"],["空","そら"],["を","を"]],[["飛びたい","とびたい","飛ぶ",30],["」"],["と","と"]],[["言う","いう","言う",5],["と","と"],["、"],["ほうき","ほうき"],["が","が"]],[["ゆっくり","ゆっくり"]],[["上がりました","あがりました","上がる",2],["。"],["初めて","はじめて"]],[["空","そら"],["を","を"]],[["飛べる","とべる","飛べる",5],["ように","ように","よう",8]],[["なった","なった","なる",0],["ん","ん"],["です","です"],["。"]]],"tr":{"az":"Mio qorxduğu üçün bir az titrədi. Amma nənənin sözləri sayəsində cəsarəti artmağa başladı. Mio «Göydə uçmaq istəyirəm» deyəndə süpürgə yavaş-yavaş havaya qalxdı. O, nəhayət ilk dəfə uçmağı bacarmışdı!","en":"Mio was frightened, so she trembled a little. But thanks to the old woman's words, she began to feel brave. When Mio said, “I want to fly,” the broom slowly rose into the air. She had finally become able to fly for the first time!","ru":"Мио было страшно, поэтому она немного дрожала. Но благодаря словам старушки к ней постепенно пришла смелость. Когда Мио сказала: «Я хочу летать», метла медленно поднялась в воздух. Впервые в жизни она смогла полететь!"}},{"t":[[["それから","それから"],["、"],["ミオ","ミオ"],["は","は"]],[["毎日","まいにち"]],[["空","そら"],["で","で","だ"]],[["練習","れんしゅう"],["する","する","する",5],["ように","ように","よう",8]],[["しました","しました","する",2],["。"],["遠く","とおく"],["まで","まで"]],[["飛べる","とべる","飛べる",5],["ように","ように","よう",8],["、"],["少し","すこし"],["ずつ","ずつ"]],[["練習","れんしゅう"],["を","を"]],[["続けました","つづけました","続ける",2],["。"],["ある日","あるひ"],["、"],["強い","つよい"]],[["風","かぜ"],["の","の"]],[["せい","せい"],["で","で"],["、"],["町","まち"],["の","の"]],[["時計","とけい"],["が","が"]],[["止まってしまいました","とまってしまいました","止まる",14],["。"],["ミオ","ミオ"],["は","は"]],[["時計","とけい"],["を","を"]],[["直す","なおす","直す",5],["ため","ため"],["に","に"],["、"],["高い","たかい"]],[["塔","とう"],["へ","へ"]],[["飛んでいきました","とんでいきました","飛ぶ",68],["。"]]],"tr":{"az":"Bundan sonra Mio hər gün səmada məşq etməyi adət etdi. Daha uzağa uça bilmək üçün tədricən məşqlərini davam etdirdi. Bir gün güclü külək üzündən şəhərin saatı dayandı. Mio saatı düzəltmək üçün hündür qülləyə uçdu.","en":"After that, Mio made a habit of practicing in the sky every day. She continued practicing little by little so that she could fly farther. One day, a strong wind caused the town clock to stop. Mio flew to the tall tower to repair it.","ru":"После этого Мио стала каждый день тренироваться в небе. Она продолжала понемногу заниматься, чтобы научиться летать дальше. Однажды из-за сильного ветра городские часы остановились. Мио полетела к высокой башне, чтобы починить их."}},{"t":[[["塔","とう"],["に","に"]],[["着く","つく","着く",5],["と","と"],["、"],["時計","とけい"],["の","の"]],[["中","なか"],["に","に"]],[["青い","あおい"],["鳥","とり"],["が","が"]],[["いました","いました","いる",2],["。"],["鳥","とり"],["の","の"]],[["羽","はね"],["が","が"]],[["時計","とけい"],["に","に"]],[["はさまっていた","はさまっていた","はさまる",47],["ん","ん"],["です","です"],["。"],["ミオ","ミオ"],["は","は"]],[["鳥","とり"],["を","を"]],[["助けて","たすけて","助ける",3],["、"],["家","いえ"],["まで","まで"]],[["連れてきました","つれてきました","連れる",23],["。"],["鳥","とり"],["は","は"],["「"],["ありがとう","ありがとう"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["ミオ","ミオ"],["の","の"]],[["肩","かた"],["に","に"]],[["止まりました","とまりました","止まる",2],["。"]]],"tr":{"az":"Qülləyə çatanda Mio saatın içində mavi quş gördü. Quşun qanadı saatın mexanizmində ilişib qalmışdı. Mio quşu xilas edib evinə gətirdi. Quş «Çox sağ ol» deyərək Mionun çiyninə qondu.","en":"When Mio reached the tower, she found a blue bird inside the clock. Its wing had become trapped in the clock mechanism. Mio rescued the bird and brought it home. “Thank you,” the bird said, landing on Mio's shoulder.","ru":"Когда Мио добралась до башни, она обнаружила внутри часов синюю птицу. Её крыло застряло в часовом механизме. Мио спасла птицу и принесла домой. «Спасибо», – сказала птица и села Мио на плечо."}},{"t":[[["その","その"]],[["夜","よる"],["、"],["鳥","とり"],["は","は"]],[["小さな","ちいさな"]],[["声","こえ"],["で","で"],["「"],["実","じつ"],["は","は"],["、"],["ぼく","ぼく"],["が","が"]],[["あの","あの"]],[["手紙","てがみ"],["を","を"]],[["書いた","かいた","書く",0],["ん","ん"],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ミオ","ミオ"],["は","は"]],[["びっくり","びっくり"],["して","して","する",3],["、"],["「"],["鳥","とり"],["も","も"]],[["字","じ"],["が","が"]],[["書ける","かける","書ける",5],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["鳥","とり"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["「"],["もちろん","もちろん"],["。"],["でも","でも"],["、"],["ほうき","ほうき"],["は","は"]],[["運転","うんてん"],["できません","できません","できる",6],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["二人","ふたり"],["は","は"]],[["大きな","おおきな"]],[["声","こえ"],["で","で","だ"]],[["笑い","わらい"],["、"],["次","つぎ"],["の","の"]],[["朝","あさ"],["も","も"]],[["いっしょ","いっしょ"],["に","に"]],[["空","そら"],["へ","へ"]],[["飛んでいきました","とんでいきました","飛ぶ",68],["。"]]],"tr":{"az":"Həmin gecə quş asta səslə «Əslində, o məktubu mən yazmışdım» dedi. Mio təəccüblənib soruşdu: «Quşlar da yazı yaza bilir?» Quş gülərək cavab verdi: «Əlbəttə. Amma süpürgə sürməyi bacarmıram». İkisi də ucadan güldü və ertəsi səhər yenə birlikdə səmaya uçdular.","en":"That night, the bird said quietly, “Actually, I wrote that letter.” Mio was astonished. “Birds can write too?” she asked. The bird laughed and replied, “Of course. But I can't drive a broom.” They both laughed loudly, and the next morning they flew into the sky together again.","ru":"В ту ночь птица тихо сказала: «Вообще-то то письмо написал я». Мио удивилась и спросила: «Птицы тоже умеют писать?» Птица рассмеялась и ответила: «Конечно. Но управлять метлой я не умею». Оба громко рассмеялись, а на следующее утро снова вместе полетели в небо."}}]},{"id":"l32c","ti":[[["おばあちゃん","おばあちゃん"],["の","の"]],[["日本","にほん"],["語","ご"],["ノート","ノート"]]],"tt":{"az":"Nənənin yapon dili dəftəri","en":"Grandma's Japanese Notebook","ru":"Тетрадь японского языка у бабушки"},"P":[{"t":[[["ある","ある","ある(連体詞)"]],[["町","まち"],["に","に"],["、"],["ハル","ハル"],["と","と"],["いう","いう","いう",5]],[["男の子","おとこのこ"],["が","が"]],[["いました","いました","いる",2],["。"],["ハル","ハル"],["の","の"]],[["おばあちゃん","おばあちゃん"],["は","は"],["、"],["外国","がいこく"],["から","から"]],[["日本","にほん"],["へ","へ"]],[["来た","きた","来る",0]],[["人","ひと"],["でした","でした","です",9],["。"],["日本","にほん"],["語","ご"],["が","が"]],[["上手に","じょうずに","上手",8]],[["話せる","はなせる","話せる",5],["ように","ように","よう",8]],[["なる","なる"],["ため","ため"],["に","に"],["、"],["毎日","まいにち"]],[["勉強","べんきょう"],["していました","していました","する",15],["。"],["ハル","ハル"],["は","は"]],[["おばあちゃん","おばあちゃん"],["に","に"]],[["日本","にほん"],["語","ご"],["を","を"]],[["教える","おしえる","教える",5],["ように","ように","よう",8]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Bir şəhərdə Haru adlı bir oğlan yaşayırdı. Harunun nənəsi xaricdən Yaponiyaya köçmüşdü. Yapon dilində yaxşı danışa bilmək üçün hər gün dərs oxuyurdu. Haru da nənəsinə yapon dili öyrətməyə başlamışdı.","en":"In a certain town, there lived a boy named Haru. Haru's grandmother had come to Japan from another country. She studied every day so that she could speak Japanese well. Haru had begun teaching his grandmother Japanese.","ru":"В одном городе жил мальчик по имени Хару. Его бабушка приехала в Японию из другой страны. Она занималась каждый день, чтобы научиться хорошо говорить по-японски. Хару стал помогать бабушке учить японский язык."}},{"t":[[["おばあちゃん","おばあちゃん"],["は","は"],["「"],["忘れない","わすれない","忘れる",19],["ように","ように","よう",8],["、"],["毎日","まいにち"]],[["三つ","みっつ"],["の","の"]],[["言葉","ことば"],["を","を"]],[["覚える","おぼえる","覚える",5],["ん","ん"],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"]],[["ノート","ノート"],["に","に"]],[["絵","え"],["を","を"]],[["描いて","えがいて","描く",3],["、"],["言葉","ことば"],["の","の"]],[["意味","いみ"],["を","を"]],[["説明","せつめい"],["しました","しました","する",2],["。"],["おばあちゃん","おばあちゃん"],["は","は"],["、"],["ハル","ハル"],["が","が"]],[["書いた","かいた","書く",0],["とおり","とおり"],["に","に"],["、"],["何回","なんかい"],["も","も"]],[["字","じ"],["を","を"]],[["書きました","かきました","書く",2],["。"],["ハル","ハル"],["の","の"]],[["おかげ","おかげ"],["で","で","だ"],["、"],["少し","すこし"],["ずつ","ずつ"]],[["漢字","かんじ"],["も","も"]],[["読める","よめる","読める",5],["ように","ように","よう",8]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Nənə «Unutmamaq üçün hər gün üç söz əzbərləyirəm» dedi. Haru dəftərdə şəkillər çəkərək sözlərin mənasını izah edirdi. Nənə Harunun yazdığı kimi hərfləri dəfələrlə yazırdı. Harunun sayəsində tədricən kanciləri də oxumağı öyrəndi.","en":"Grandma said, “I learn three words every day so that I won't forget them.” Haru drew pictures in her notebook and explained the meanings of the words. Grandma wrote the characters many times, exactly as Haru had written them. Thanks to Haru, she gradually learned to read kanji too.","ru":"Бабушка говорила: «Я каждый день учу три слова, чтобы их не забыть». Хару рисовал картинки в тетради и объяснял значения слов. Бабушка много раз переписывала иероглифы точно так, как их написал Хару. Благодаря ему она постепенно научилась читать и кандзи."}},{"t":[[["ある日","あるひ"],["、"],["おばあちゃん","おばあちゃん"],["は","は"],["「"],["明日","あした"],["、"],["一人","ひとり"],["で","で"]],[["買い物","かいもの"],["に","に"]],[["行きたい","いきたい","行く",30],["ん","ん"],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"]],[["おばあちゃん","おばあちゃん"],["に","に"],["、"],["わからない","わからない","わかる",19]],[["言葉","ことば"],["が","が"]],[["あったら","あったら","ある",44]],[["店","みせ"],["の","の"]],[["人","ひと"],["に","に"]],[["聞く","きく","聞く",5],["ように","ように","よう",8]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["買い物","かいもの"],["の","の"],["ため","ため"],["に","に"],["、"],["小さな","ちいさな"]],[["メモ","メモ"],["を","を"]],[["作ってあげました","つくってあげました","作る",60],["。"],["メモ","メモ"],["に","に"],["は","は"],["「"],["卵","たまご"],["、"],["牛乳","ぎゅうにゅう"],["、"],["パン","パン"],["」"],["と","と"]],[["書きました","かきました","書く",2],["。"]]],"tr":{"az":"Bir gün nənə «Sabah alış-verişə tək getmək istəyirəm» dedi. Haru ona başa düşmədiyi sözləri mağaza işçisindən soruşmağı tapşırdı. Sonra alış-veriş üçün kiçik bir qeyd hazırladı. Qeydə «Yumurta, süd, çörək» yazdı.","en":"One day, Grandma said, “Tomorrow, I want to go shopping by myself.” Haru told her to ask a shop worker whenever she did not understand a word. Then he made a small shopping note for her. On it, he wrote, “Eggs, milk, bread.”","ru":"Однажды бабушка сказала: «Завтра я хочу сама сходить за покупками». Хару посоветовал ей спрашивать работников магазина, если какое-нибудь слово будет непонятно. Затем он составил для неё небольшой список покупок. В нём было написано: «Яйца, молоко, хлеб»."}},{"t":[[["次","つぎ"],["の","の"]],[["日","ひ"],["、"],["おばあちゃん","おばあちゃん"],["は","は"]],[["メモ","メモ"],["を","を"]],[["持って","もって","持つ",3]],[["スーパー","スーパー"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["でも","でも"],["、"],["眼鏡","めがね"],["を","を"]],[["忘れた","わすれた","忘れる",0]],[["せい","せい"],["で","で"],["、"],["小さな","ちいさな"]],[["字","じ"],["が","が"]],[["読めませんでした","よめませんでした","読める",4],["。"],["どれ","どれ"],["が","が"]],[["牛乳","ぎゅうにゅう"],["か","か"]],[["わからなかった","わからなかった","わかる",22],["の","の"],["で","で","だ"],["、"],["店員","てんいん"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["店員","てんいん"],["は","は"]],[["笑顔","えがお"],["で","で","だ"]],[["牛乳","ぎゅうにゅう"],["の","の"]],[["場所","ばしょ"],["を","を"]],[["教えてくれました","おしえてくれました","教える",54],["。"]]],"tr":{"az":"Ertəsi gün nənə qeydi götürüb supermarketə getdi. Amma eynəyini unutduğu üçün kiçik yazıları oxuya bilmirdi. Hansının süd olduğunu bilmədiyinə görə mağaza işçisindən soruşdu. İşçi gülümsəyərək südün yerini göstərdi.","en":"The next day, Grandma took the note and went to the supermarket. But because she had forgotten her glasses, she could not read the small writing. She did not know which product was milk, so she asked a shop assistant. The assistant smiled and showed her where the milk was.","ru":"На следующий день бабушка взяла список и пошла в супермаркет. Но из-за забытых очков она не могла прочитать мелкие буквы. Она не знала, где молоко, поэтому спросила продавца. Продавец улыбнулся и показал ей, где оно стоит."}},{"t":[[["家","いえ"],["へ","へ"]],[["帰ってくる","かえってくる","帰る",96],["と","と"],["、"],["おばあちゃん","おばあちゃん"],["は","は"]],[["大きな","おおきな"]],[["袋","ふくろ"],["を","を"]],[["持っていました","もっていました","持つ",15],["。"],["ハル","ハル"],["は","は"]],[["中","なか"],["に","に"]],[["何","なに"],["が","が"]],[["入っている","はいっている","入る",26],["か","か"],["、"],["楽しみ","たのしみ"],["に","に"]],[["していました","していました","する",15],["。"],["でも","でも"],["、"],["袋","ふくろ"],["の","の"]],[["中","なか"],["に","に"],["は","は"]],[["卵","たまご"],["も","も"]],[["牛乳","ぎゅうにゅう"],["も","も"]],[["ありませんでした","ありませんでした","ある",4],["。"],["かわり","かわり"],["に","に"],["、"],["猫","ねこ"],["の","の"]],[["ご飯","ごはん"],["が","が"]],[["三つ","みっつ"],["と","と"],["、"],["大きな","おおきな"]],[["魚","さかな"],["が","が"]],[["一匹","いっぴき"]],[["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Nənə evə qayıdanda əlində böyük bir torba var idi. Haru içində nə olduğunu səbirsizliklə gözləyirdi. Amma torbada nə yumurta, nə də süd var idi. Onların əvəzinə üç paket pişik yemi və bir böyük balıq var idi.","en":"When Grandma came home, she was carrying a large bag. Haru was excited to see what was inside. But there were no eggs or milk in the bag. Instead, there were three packets of cat food and one large fish.","ru":"Когда бабушка вернулась домой, она несла большой пакет. Хару с нетерпением ждал, что же внутри. Но в пакете не было ни яиц, ни молока. Вместо них там лежали три упаковки кошачьего корма и одна большая рыба."}},{"t":[[["ハル","ハル"],["は","は"],["「"],["どう","どう"],["して","して","する",3]],[["猫","ねこ"],["の","の"]],[["ご飯","ごはん"],["を","を"]],[["買ってきた","かってきた","買う",84],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["おばあちゃん","おばあちゃん"],["は","は"],["「"],["店","みせ"],["の","の"]],[["前","まえ"],["に","に"]],[["おなか","おなか"],["が","が"]],[["すいた","すいた","すく",0]],[["猫","ねこ"],["が","が"]],[["いた","いた","いる",0],["ん","ん"],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["「"],["かわいそう","かわいそう"],["だった","だった","です",9],["の","の"],["で","で","だ"],["、"],["ご飯","ごはん"],["を","を"]],[["買ってあげた","かってあげた","買う",97],["ん","ん"],["です","です"],["」"],["と","と"],["も","も"]],[["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["、"],["猫","ねこ"],["が","が"]],[["もう","もう"]],[["おなか","おなか"],["いっぱい","いっぱい"],["か","か"],["どう","どう"],["か","か"],["、"],["気","き"],["に","に"]],[["なりました","なりました","なる",2],["。"]]],"tr":{"az":"Haru soruşdu: «Niyə pişik yemi almısan?» Nənə cavab verdi: «Mağazanın qabağında ac bir pişik var idi». Sonra əlavə etdi: «Ona yazığım gəldi, ona görə yemək aldım». Haru pişiyin artıq doyub-doymadığını düşünməyə başladı.","en":"Haru asked, “Why did you buy cat food?” Grandma replied, “There was a hungry cat in front of the store.” She added, “I felt sorry for it, so I bought it some food.” Haru began wondering whether the cat had eaten enough.","ru":"Хару спросил: «Почему ты купила кошачий корм?» Бабушка ответила: «Перед магазином сидела голодная кошка». Она добавила: «Мне стало её жалко, поэтому я купила ей еду». Хару задумался, наелась ли уже кошка."}},{"t":[[["その","その"]],[["とき","とき"],["、"],["玄関","げんかん"],["から","から"],["「"],["ニャー","ニャー"],["」"],["と","と"],["いう","いう","いう",5]],[["声","こえ"],["が","が"]],[["聞こえました","きこえました","聞こえる",2],["。"],["ハル","ハル"],["が","が"]],[["ドア","ドア"],["を","を"]],[["開ける","あける","開ける",5],["と","と"],["、"],["さっき","さっき"],["の","の"]],[["猫","ねこ"],["が","が"]],[["入ってきました","はいってきました","入る",23],["。"],["おばあちゃん","おばあちゃん"],["は","は"],["「"],["家","いえ"],["まで","まで"]],[["ついてきた","ついてきた","つく",84],["ん","ん"],["です","です"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"],["ハル","ハル"],["は","は"]],[["猫","ねこ"],["が","が"]],[["怖がらない","こわがらない","怖い",19],["ように","ように","よう",8],["、"],["静かに","しずかに","静か",8]],[["座りました","すわりました","座る",2],["。"]]],"tr":{"az":"Elə bu vaxt giriş qapısından «Miyau» səsi eşidildi. Haru qapını açanda bayaqkı pişik içəri girdi. Nənə gülərək «Evimə qədər arxamca gəlib» dedi. Haru pişik qorxmasın deyə sakitcə oturdu.","en":"Just then, they heard a “Meow” from the entrance. When Haru opened the door, the same cat came inside. Grandma laughed and said, “It followed me all the way home.” Haru sat quietly so that the cat would not be frightened.","ru":"В этот момент у входной двери послышалось «Мяу». Когда Хару открыл дверь, внутрь вошла та самая кошка. Бабушка рассмеялась: «Она шла за мной до самого дома». Хару тихо сел, чтобы кошка не испугалась."}},{"t":[[["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["ハル","ハル"],["は","は"]],[["おばあちゃん","おばあちゃん"],["に","に"]],[["買い物","かいもの"],["の","の"]],[["練習","れんしゅう"],["を","を"]],[["もう","もう"]],[["一度","いちど"]],[["する","する","する",5],["ように","ように","よう",8]],[["頼みました","たのみました","頼む",2],["。"],["おばあちゃん","おばあちゃん"],["は","は"],["「"],["今度","こんど"],["は","は"]],[["眼鏡","めがね"],["を","を"]],[["忘れない","わすれない","忘れる",19],["ように","ように","よう",8]],[["します","します","する",11],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["でも","でも"],["、"],["猫","ねこ"],["は","は"]],[["メモ","メモ"],["を","を"]],[["口","くち"],["に","に"]],[["入れて","いれて","入れる",3],["、"],["庭","にわ"],["へ","へ"]],[["走っていきました","はしっていきました","走る",25],["。"],["二人","ふたり"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["ノート","ノート"],["に","に"]],[["新しい","あたらしい"]],[["言葉","ことば"],["を","を"]],[["書きました","かきました","書く",2],["。"],["それ","それ"],["は","は"],["「"],["猫","ねこ"],["の","の"]],[["せい","せい"],["で","で"],["、"],["また","また"]],[["買い物","かいもの"],["に","に"]],[["行きます","いきます","行く",11],["」"],["でした","でした","です",9],["。"]]],"tr":{"az":"Ertəsi səhər Haru nənəsindən alış-veriş məşqini bir daha etməsini xahiş etdi. Nənə «Bu dəfə eynəyimi unutmamağa çalışacağam» dedi. Amma pişik qeydi ağzına alıb həyətə qaçdı. İkisi də gülərək dəftərə yeni bir cümlə yazdı. Cümlə belə idi: «Pişiyin üzündən yenə alış-verişə gedirik».","en":"The next morning, Haru asked Grandma to practice shopping once more. Grandma replied, “This time, I'll make sure not to forget my glasses.” But the cat picked up the shopping note in its mouth and ran into the garden. They both laughed and wrote a new sentence in the notebook. It said, “Because of the cat, we're going shopping again.”","ru":"На следующее утро Хару попросил бабушку ещё раз потренироваться ходить за покупками. Бабушка ответила: «На этот раз постараюсь не забыть очки». Но кошка схватила список покупок зубами и убежала в сад. Оба рассмеялись и записали в тетрадь новое предложение. Оно гласило: «Из-за кошки нам снова придётся идти за покупками»."}}]}],"G":{"あげる":{"b":"あげる","p":"v","m":{"az":"vermək, hədiyyə etmək","en":"give","ru":"давать, дарить"},"n":{"az":"Alan şəxs に, verilən şey を ilə işlənir: 友達に本をあげる; danışana verilən şey üçün adətən くれる işlənir.","en":"The recipient takes に and the gift を, as in 友達に本をあげる; giving to the speaker is usually expressed with くれる.","ru":"Получатель обозначается с に, подарок с を: 友達に本をあげる; когда дают говорящему, обычно используется くれる."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"ありがとう":{"b":"ありがとう","p":"ex","m":{"az":"sağ ol","en":"thank you","ru":"спасибо"},"n":{"az":"Daha nəzakətli: ありがとうございます.","en":"More polite: ありがとうございます.","ru":"Вежливее: ありがとうございます."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"あんな":{"b":"あんな","p":"dm","m":{"az":"elə, o cür","en":"that kind of, like that","ru":"такой, подобный тому"},"n":{"az":"Uzaqda olan və ya əvvəldən məlum xüsusiyyətə işarə edir; あんな人 belə adam deməkdir.","en":"Points to a distant or previously mentioned kind; あんな人 means that kind of person.","ru":"Указывает на удалённый или уже упомянутый тип; あんな人 означает такой человек."}},"い":{"b":"い","p":"in","m":{"az":"hey, ay","en":"hey, oi","ru":"эй, слушай"},"n":{"az":"Kontekstdən asılı olaraq qeyri-rəsmi səslənmə və ya nida kimi işlənir.","en":"Depending on context, it is an informal call or exclamation.","ru":"В зависимости от контекста употребляется как неформальное обращение или возглас."}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いっしょ":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlikdə","en":"together","ru":"вместе"},"n":{"az":"いっしょに = birlikdə.","en":"いっしょに = together.","ru":"いっしょに = вместе."}},"いっぱい":{"b":"いっぱい","p":"ad","m":{"az":"çox, dolu","en":"a lot, full","ru":"много, полно"},"n":{"az":"いっぱい食べる “çox yemək”, おなかがいっぱい isə “tox olmaq” deməkdir.","en":"いっぱい食べる means “eat a lot,” while おなかがいっぱい means “be full.”","ru":"いっぱい食べる означает «много есть», а おなかがいっぱい означает «быть сытым»."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"おかげ":{"b":"おかげ (おかげ)","p":"n","m":{"az":"sayəsində; köməyi ilə","en":"thanks to; owing to","ru":"благодаря; заслуга"},"n":{"az":"おかげで adətən müsbət səbəbi bildirir: 先生のおかげで合格した.","en":"おかげで usually gives a positive cause: 先生のおかげで合格した.","ru":"おかげで обычно указывает на положительную причину: 先生のおかげで合格した."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おなか":{"b":"おなか","p":"n","m":{"az":"qarın","en":"stomach, belly","ru":"живот"},"n":{"az":"おなかがすく “acmaq”, おなかがいっぱい isə “tox olmaq” deməkdir.","en":"おなかがすく means “get hungry,” and おなかがいっぱい means “be full.”","ru":"おなかがすく означает «проголодаться», а おなかがいっぱい означает «быть сытым»."}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おばあちゃん":{"b":"おばあちゃん","p":"n","m":{"az":"nənə; yaşlı qadın","en":"grandma; elderly woman","ru":"бабушка; пожилая женщина"},"n":{"az":"Nənəyə və ya yaşlı qadına mehriban müraciət kimi də işlənir.","en":"Also used as an affectionate address to a grandmother or elderly woman.","ru":"Также используется как ласковое обращение к бабушке или пожилой женщине."}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"かわいそう":{"b":"かわいそう","p":"an","m":{"az":"yazıq; acınacaqlı","en":"poor; pitiful","ru":"бедный; жалкий"},"n":{"az":"Na-sifətdir: かわいそうな猫 yazıq pişik deməkdir və かわいい ilə eyni deyil.","en":"A na-adjective: かわいそうな猫 means a poor cat; it does not mean cute like かわいい.","ru":"На-прилагательное: かわいそうな猫 означает бедную кошку; не путать с かわいい, милый."}},"かわり":{"b":"代わり (かわり)","p":"n","m":{"az":"əvəz; yerinə","en":"substitute; replacement","ru":"замена; вместо"},"n":{"az":"〜の代わりに kiminsə və ya nəyinsə əvəzinə deməkdir.","en":"〜の代わりに means instead of someone or something.","ru":"〜の代わりに означает вместо кого-либо или чего-либо."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"がんばる":{"b":"頑張る (がんばる)","p":"v","m":{"az":"çalışmaq, səy göstərmək","en":"to do one's best, to persevere","ru":"стараться, прилагать усилия"},"n":{"az":"頑張って kiməsə uğur arzulamaq və ya onu ruhlandırmaq üçün işlənir.","en":"頑張って is used to encourage someone or tell them to do their best.","ru":"頑張って используется для поддержки человека и пожелания ему успеха."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こっち":{"b":"こっち (こっち)","p":"pr","m":{"az":"bu tərəf; bura","en":"this way; over here","ru":"сюда; в эту сторону"},"n":{"az":"こちら sözünün qeyri-rəsmi formasıdır və danışana yaxın istiqaməti bildirir.","en":"Casual form of こちら, indicating the direction near the speaker.","ru":"Разговорная форма こちら, указывает на направление рядом с говорящим."}},"ごらん":{"b":"ごらん","p":"n","m":{"az":"baxma, bax gör","en":"looking, have a look","ru":"смотрение, посмотри"},"n":{"az":"ご覧 olmaqla nəzakətli baxma ifadəsidir; 見てごらん isə səmimi şəkildə bax gör deməkdir.","en":"Usually written ご覧; 見てごらん is a familiar invitation to look or try looking.","ru":"Обычно пишется ご覧; 見てごらん означает дружеское предложение посмотреть."}},"ご飯":{"b":"ご飯 (ごはん)","p":"n","m":{"az":"bişmiş düyü, yemək","en":"cooked rice, meal","ru":"варёный рис, еда"},"n":{"az":"ご飯 həm bişmiş düyü, həm də ümumilikdə yemək deməkdir.","en":"ご飯 can mean cooked rice or a meal.","ru":"ご飯 может означать варёный рис или приём пищи."}},"さっき":{"b":"さっき","p":"n","m":{"az":"bayaq, bir az əvvəl","en":"a moment ago","ru":"только что"}},"すく":{"b":"すく (空く)","p":"v","m":{"az":"acmaq, boşalmaq","en":"to become empty, to get hungry","ru":"опустеть, проголодаться"},"n":{"az":"I qrup feldir: おなかがすきました = acdım; 空く həm də boşalmaq deməkdir.","en":"A Group 1 verb: おなかがすきました = I got hungry; 空く can also mean to become empty.","ru":"Глагол I группы: おなかがすきました = я проголодался; 空く также означает опустеть."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"せい":{"b":"せい","p":"n","m":{"az":"günah, səbəb","en":"fault, blame","ru":"вина, причина"},"n":{"az":"〜のせいで mənfi nəticənin səbəbini bildirir; 雨のせいで yağış üzündən deməkdir.","en":"〜のせいで attributes a negative result to a cause, as in 雨のせいで, because of the rain.","ru":"〜のせいで указывает причину плохого результата, например 雨のせいで - из-за дождя."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"ため":{"b":"ため (ため)","p":"n","m":{"az":"məqsəd; səbəb; xeyir","en":"purpose; reason; sake","ru":"цель; причина; польза"},"n":{"az":"〜ために məqsəd və ya səbəb bildirir: 勉強するために oxumaq üçün.","en":"〜ために expresses purpose or cause; 勉強するために means in order to study.","ru":"〜ために выражает цель или причину; 勉強するために означает чтобы учиться."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"つく":{"b":"つく (着く)","p":"v","m":{"az":"çatmaq, yetişmək","en":"to arrive, to reach","ru":"прибывать, добираться"},"n":{"az":"I qrup feldir: 駅に着く = stansiyaya çatmaq; つきませんでした = çatmadı.","en":"A Group 1 verb: 駅に着く = to arrive at the station; つきませんでした = did not arrive.","ru":"Глагол I группы: 駅に着く = прибыть на станцию; つきませんでした = не прибыл."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とおり":{"b":"通り (とおり)","p":"n","m":{"az":"küçə, qayda, şəkildə","en":"street, way, as described","ru":"улица, способ, как указано"},"n":{"az":"〜のとおり və 〜たとおり deyilən və ya edilən kimi mənasını verir.","en":"〜のとおり and 〜たとおり mean according to or just as something was said or done.","ru":"〜のとおり и 〜たとおり означают согласно чему-либо или так, как было сказано или сделано."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"どれ":{"b":"どれ","p":"pr","m":{"az":"hansı, hansısı","en":"which one","ru":"который, какой из них"},"n":{"az":"Bir neçə şeydən seçim üçündür; isimdən əvvəl どの işlənir.","en":"Used to choose among items; use どの before a noun.","ru":"Используется для выбора; перед существительным ставится どの."}},"なかなか":{"b":"なかなか","p":"ad","m":{"az":"xeyli, heç cür","en":"quite, not easily","ru":"довольно, никак"},"n":{"az":"Təsdiqdə “xeyli, kifayət qədər”, inkarda isə “asanlıqla olmur” mənasını verir: なかなか来ません “heç cür gəlmir”.","en":"With an affirmative it means “quite”; with a negative it means “not easily” or “still not,” as in なかなか来ません “is taking a long time to come.”","ru":"С утверждением означает «довольно», с отрицанием «никак, нелегко»: なかなか来ません «всё никак не приходит»."}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"はさまる":{"b":"挟まる (はさまる)","p":"v","m":{"az":"arasında qalmaq, sıxışmaq","en":"to get caught between, be wedged","ru":"застрять между, оказаться зажатым"},"n":{"az":"自動詞dir; 挟む (arasına sıxmaq) ilə cütdür, はさまっていた keçmişdə davam edən vəziyyəti bildirir.","en":"Intransitive; pairs with 挟む, and はさまっていた describes a past state of being stuck.","ru":"Непереходный глагол; пара к 挟む, а はさまっていた описывает состояние зажатости в прошлом."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"ふう":{"b":"風 (ふう)","p":"n","m":{"az":"tərz, üsul, görünüş","en":"style, manner, way","ru":"стиль, манера, способ"},"n":{"az":"こんなふうに bu cür, 〜というふうに isə belə bir şəkildə deməkdir.","en":"こんなふうに means in this way, while 〜というふうに means in such a manner.","ru":"こんなふうに означает таким образом, а 〜というふうに - в таком виде или таким способом."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほうき":{"b":"箒 (ほうき)","p":"n","m":{"az":"süpürgə","en":"broom","ru":"метла, веник"}},"ほか":{"b":"他 (ほか)","p":"n","m":{"az":"başqa; digəri","en":"other; elsewhere","ru":"другой; остальное"},"n":{"az":"ほかの人 başqa adam, ほかに isə əlavə olaraq deməkdir.","en":"ほかの人 means another person, and ほかに means additionally.","ru":"ほかの人 означает другой человек, а ほかに - кроме того."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みにくい":{"b":"醜い (みにくい)","p":"ai","m":{"az":"çirkin, eybəcər","en":"ugly, unsightly","ru":"уродливый, некрасивый"},"n":{"az":"い-sifətdir; 醜い görünüşə aiddir, 見にくい isə görməkdə çətinlik deməkdir.","en":"An i-adjective; 醜い means ugly, whereas 見にくい means hard to see.","ru":"Прилагательное на い; 醜い означает некрасивый, а 見にくい - трудно разглядеть."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかし":{"b":"昔 (むかし)","p":"n","m":{"az":"çox qədim zaman","en":"long ago","ru":"давным-давно"},"n":{"az":"むかし むかし = 'biri var idi, biri yox idi' – nağılların başlanğıcı.","en":"むかし むかし = 'once upon a time' – the opening of tales.","ru":"むかし むかし = 'давным-давно' – начало сказок."}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もちろん":{"b":"もちろん","p":"ad","m":{"az":"əlbəttə, şübhəsiz","en":"of course, certainly","ru":"конечно, разумеется"}},"やがて":{"b":"やがて","p":"ad","m":{"az":"bir müddət sonra; nəhayət","en":"before long; eventually","ru":"вскоре; со временем"}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"アヒル":{"b":"アヒル","p":"n","m":{"az":"ev ördəyi","en":"domestic duck","ru":"домашняя утка"}},"アヒルたち":{"b":"アヒルたち","p":"n","m":{"az":"ev ördəkləri","en":"domestic ducks","ru":"домашние утки"},"n":{"az":"たち burada bir neçə ördəkdən ibarət qrupu bildirir.","en":"たち indicates a group of ducks here.","ru":"たち здесь обозначает группу уток."}},"スーパー":{"b":"スーパー","p":"n","m":{"az":"supermarket","en":"supermarket","ru":"супермаркет"},"n":{"az":"スーパーマーケット sözünün qısaldılmış formasıdır, başqa kontekstdə super mənasında da işlənir.","en":"Short for スーパーマーケット; in other contexts it can also mean super.","ru":"Сокращение от スーパーマーケット; в других контекстах также означает супер."}},"ドア":{"b":"ドア","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"ニャー":{"b":"ニャー (にゃー)","p":"in","m":{"az":"miyov!","en":"meow!","ru":"мяу!"},"n":{"az":"Pişiyin səsini təqlid edir.","en":"Imitates the sound of a cat.","ru":"Передаёт звук мяуканья кошки."}},"ノート":{"b":"ノート","p":"n","m":{"az":"dəftər","en":"notebook","ru":"тетрадь"}},"ハル":{"b":"ハル","p":"nm","m":{"az":"Haru","en":"Haru","ru":"Хару"}},"パン":{"b":"パン","p":"n","m":{"az":"çörək","en":"bread","ru":"хлеб"}},"ミオ":{"b":"ミオ (ミオ)","p":"nm","m":{"az":"Mio; şəxs adı","en":"Mio; personal name","ru":"Мио; личное имя"}},"メモ":{"b":"メモ (めも)","p":"n","m":{"az":"qeyd, qısa yazı","en":"note, memo","ru":"заметка, записка"}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一匹":{"b":"一匹 (いっぴき)","p":"nu","m":{"az":"bir heyvan, bir ədəd","en":"one small animal","ru":"одно животное"},"n":{"az":"匹 kiçik heyvanlar üçündür, 一匹 いっぴき oxunur.","en":"匹 counts small animals, and 一匹 is pronounced いっぴき.","ru":"Счётный суффикс 匹 для небольших животных, 一匹 читается いっぴき."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一羽":{"b":"一羽 (いちわ)","p":"nu","m":{"az":"bir quş","en":"one bird","ru":"одна птица"},"n":{"az":"羽 quşları və ənənəvi olaraq dovşanları sayır: 一羽（いちわ）.","en":"羽 counts birds and traditionally rabbits: 一羽（いちわ）.","ru":"羽 используется для птиц и традиционно для кроликов: 一羽（いちわ）."}},"三つ":{"b":"三つ (みっつ)","p":"n","m":{"az":"üç (dənə)","en":"three (things)","ru":"три (штуки)"}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上がる":{"b":"上がる (あがる)","p":"v","m":{"az":"qalxmaq","en":"to go up, rise","ru":"подниматься"}},"上手":{"b":"上手 (じょうず)","p":"an","m":{"az":"bacarıqlı, yaxşı bacaran","en":"skillful, good at","ru":"умелый, хорошо умеющий"},"n":{"az":"な-sifətdir: ピアノが上手です = pianoda yaxşı çalır.","en":"A na-adjective: ピアノが上手です = is good at playing piano.","ru":"な-прилагательное: ピアノが上手です = хорошо играет на пианино."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"仲よく":{"b":"仲よく (なかよく)","p":"ad","m":{"az":"mehribancasına, yola gedərək","en":"amicably, on good terms","ru":"дружно, в хороших отношениях"},"n":{"az":"仲がいい ifadəsi ilə bağlıdır; 仲よく遊ぶ mehribancasına oynamaqdır.","en":"Related to 仲がいい; 仲よく遊ぶ means to play together amicably.","ru":"Связано с 仲がいい; 仲よく遊ぶ означает дружно играть."}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"何回":{"b":"何回 (なんかい)","p":"ex","m":{"az":"neçə dəfə","en":"how many times","ru":"сколько раз"},"n":{"az":"回 hərəkətlərin sayını bildirir; 何回も dəfələrlə deməkdir.","en":"回 counts occurrences; 何回も means many times.","ru":"回 считает повторения; 何回も означает много раз."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"優しい":{"b":"優しい (やさしい)","p":"ai","m":{"az":"mehriban, mülayim","en":"kind, gentle","ru":"добрый, мягкий"},"n":{"az":"İ-sifətidir; “asan” mənasındakı 易しい ilə eyni oxunur.","en":"An i-adjective; it has the same reading as 易しい “easy.”","ru":"Прилагательное на い; читается так же, как 易しい «лёгкий»."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"六羽":{"b":"六羽 (ろくわ)","p":"nu","m":{"az":"altı quş, altı ədəd quş","en":"six birds, six feathered animals","ru":"шесть птиц"},"n":{"az":"羽 quşlar və dovşanlar üçün sayğacdır; 六羽 ろくわ, 三羽 さんば oxunur.","en":"羽 counts birds and rabbits; 六羽 is ろくわ and 三羽 is さんば.","ru":"羽 используется для птиц и кроликов; 六羽 читается ろくわ, а 三羽 - さんば."}},"冬":{"b":"冬 (ふゆ)","p":"n","m":{"az":"qış","en":"winter","ru":"зима"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"勇気":{"b":"勇気 (ゆうき)","p":"n","m":{"az":"cəsarət, ürək","en":"courage, bravery","ru":"смелость, мужество"},"n":{"az":"勇気を出す cəsarətini toplamaq deməkdir.","en":"勇気を出す means to gather one's courage.","ru":"勇気を出す означает набраться смелости."}},"勉強":{"b":"勉強 (べんきょう)","p":"n","m":{"az":"dərs oxuma; təhsil","en":"study; learning","ru":"учёба; обучение"},"n":{"az":"勉強する = dərs oxumaq, öyrənmək.","en":"勉強する means to study.","ru":"勉強する означает учиться, изучать."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"卵":{"b":"卵 (たまご)","p":"n","m":{"az":"yumurta","en":"egg","ru":"яйцо"}},"友だち":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг, подруга"}},"口":{"b":"口 (くち)","p":"n","m":{"az":"ağız, açılış","en":"mouth, opening","ru":"рот, отверстие"}},"古い":{"b":"古い (ふるい)","p":"ai","m":{"az":"köhnə; qədim","en":"old","ru":"старый; древний"},"n":{"az":"İ-sifətdir; əşya və tikililər üçün işlənir, insanın yaşını bildirmir.","en":"An i-adjective used for things and buildings, not a person's age.","ru":"И-прилагательное для вещей и зданий, не для возраста человека."}},"同じ":{"b":"同じ (おなじ)","p":"an","m":{"az":"eyni","en":"same","ru":"одинаковый, тот же"},"n":{"az":"İsimdən əvvəl な almır: 同じ月 = eyni Ay.","en":"Takes no な before a noun: 同じ月 = the same moon.","ru":"Перед сущ. без な: 同じ月 = та же луна."}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"喜ぶ":{"b":"喜ぶ (よろこぶ)","p":"v","m":{"az":"sevinmək, şadlanmaq","en":"to rejoice, to be pleased","ru":"радоваться, обрадоваться"},"n":{"az":"I qrup feldir: 喜びました = sevindi; プレゼントを喜ぶ = hədiyyəyə sevinmək.","en":"A Group 1 verb: 喜びました = was pleased; プレゼントを喜ぶ = to be delighted with a gift.","ru":"Глагол I группы: 喜びました = обрадовался; プレゼントを喜ぶ = радоваться подарку."}},"地面":{"b":"地面 (じめん)","p":"n","m":{"az":"yer, torpaq səthi","en":"ground, earth's surface","ru":"земля, поверхность земли"}},"場所":{"b":"場所 (ばしょ)","p":"n","m":{"az":"yer","en":"place","ru":"место"}},"塔":{"b":"塔 (とう)","p":"n","m":{"az":"qüllə","en":"tower","ru":"башня"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"外国":{"b":"外国 (がいこく)","p":"n","m":{"az":"xarici ölkə","en":"foreign country","ru":"зарубежная страна"}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"子ども":{"b":"子ども (こども)","p":"n","m":{"az":"uşaq","en":"child","ru":"ребёнок"}},"字":{"b":"字 (じ)","p":"n","m":{"az":"hərf, yazı","en":"character, handwriting","ru":"письменный знак, почерк"}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"実":{"b":"実 (み)","p":"n","m":{"az":"meyvə, bar, toxum","en":"fruit, berry, seed","ru":"плод, ягода, семя"},"n":{"az":"実がなる - ağacın və ya bitkinin bar verməsi.","en":"実がなる means for a tree or plant to bear fruit.","ru":"実がなる означает плодоносить."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"寒い":{"b":"寒い (さむい)","p":"ai","m":{"az":"soyuq","en":"cold, chilly","ru":"холодный, прохладный"},"n":{"az":"い-sifətdir; əsasən hava üçün işlənir, toxunanda soyuq əşyalar üçün 冷たい deyilir.","en":"An i-adjective mainly for cold weather; use 冷たい for cold objects.","ru":"Прилагательное на い, обычно о погоде; для холодных предметов используют 冷たい."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"店員":{"b":"店員 (てんいん)","p":"n","m":{"az":"mağaza işçisi, satıcı","en":"shop assistant, store clerk","ru":"продавец, сотрудник магазина"}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"待つ":{"b":"待つ (まつ)","p":"v","m":{"az":"gözləmək","en":"wait for","ru":"ждать"},"n":{"az":"Gözlənilən şəxs və ya şey を ilə işlənir; て-forması 待って olur.","en":"The person or thing awaited takes を; the て-form is 待って.","ru":"Тот, кого ждут, или то, чего ждут, обозначается с を; форма на て: 待って."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"怖い":{"b":"怖い (こわい)","p":"ai","m":{"az":"qorxulu, vahiməli","en":"scary, frightening","ru":"страшный, пугающий"},"n":{"az":"い-sifətdir: 怖い話 = qorxulu hekayə; 怖くない = qorxulu deyil.","en":"An i-adjective: 怖い話 = scary story; 怖くない = not scary.","ru":"Прилагательное на い: 怖い話 = страшная история; 怖くない = не страшно."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"悲しい":{"b":"悲しい (かなしい)","p":"ai","m":{"az":"kədərli","en":"sad","ru":"грустный"},"n":{"az":"İ-sifətidir; 悲しく zərf formasıdır və “kədərli şəkildə” mənasını verir.","en":"An i-adjective; 悲しく is its adverbial form, meaning “sadly.”","ru":"Прилагательное на い; 悲しく является наречной формой со значением «грустно»."}},"意味":{"b":"意味 (いみ)","p":"n","m":{"az":"məna; anlam","en":"meaning; sense","ru":"значение; смысл"}},"手紙":{"b":"手紙 (てがみ)","p":"n","m":{"az":"məktub","en":"letter","ru":"письмо"}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"描く":{"b":"描く (かく)","p":"v","m":{"az":"şəkil çəkmək, təsvir etmək","en":"to draw, to depict","ru":"рисовать, изображать"},"n":{"az":"Rəsm çəkmək üçün 描く, mətn yazmaq üçün 書く işlənir.","en":"描く is used for drawing pictures, while 書く is used for writing text.","ru":"描く используется для рисования, а 書く - для написания текста."}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日本":{"b":"日本 (にほん)","p":"n","m":{"az":"Yaponiya","en":"Japan","ru":"Япония"}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"春":{"b":"春 (はる)","p":"n","m":{"az":"yaz (fəsil)","en":"spring","ru":"весна"}},"時計":{"b":"時計 (とけい)","p":"n","m":{"az":"saat","en":"clock; watch","ru":"часы"}},"暖かい":{"b":"暖かい (あたたかい)","p":"ai","m":{"az":"isti, ilıq","en":"warm","ru":"тёплый"},"n":{"az":"İ-sifətidir; əsasən hava və mühitin istiliyini, 温かい isə əşya, yemək və münasibətin istiliyini bildirir.","en":"An i-adjective mainly describing warm weather or surroundings; 温かい is used for objects, food, and personal warmth.","ru":"Прилагательное на い, обычно о тёплой погоде или обстановке; 温かい употребляется о предметах, еде и душевном тепле."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"書ける":{"b":"書ける (かける)","p":"v","m":{"az":"yaza bilmək","en":"can write","ru":"мочь писать"},"n":{"az":"書く felinin potensial formasıdır; 漢字が書ける kanci yaza bilmək deməkdir.","en":"Potential form of 書く; 漢字が書ける means to be able to write kanji.","ru":"Потенциальная форма 書く; 漢字が書ける означает уметь писать кандзи."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"本":{"b":"本 (ほん)","p":"n","m":{"az":"kitab","en":"book","ru":"книга"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"東":{"b":"東 (ひがし)","p":"n","m":{"az":"şərq","en":"east","ru":"восток"}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"楽しみ":{"b":"楽しみ (たのしみ)","p":"n","m":{"az":"sevinc; səbirsizliklə gözlənilən şey","en":"pleasure; something to look forward to","ru":"радость; предвкушение"},"n":{"az":"楽しみにしています səbirsizliklə gözləyirəm deməkdir.","en":"楽しみにしています means I am looking forward to it.","ru":"楽しみにしています означает с нетерпением жду."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"気":{"b":"気 (き)","p":"n","m":{"az":"ruh, əhval, niyyət","en":"spirit, mood, intention","ru":"дух, настроение, намерение"},"n":{"az":"気をつける = diqqətli olmaq; 気になる = maraqlandırmaq və ya narahat etmək.","en":"気をつける = to be careful; 気になる = to be curious or concerned.","ru":"気をつける = быть осторожным; 気になる = интересовать или беспокоить."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"池":{"b":"池 (いけ)","p":"n","m":{"az":"gölməçə, kiçik göl","en":"pond","ru":"пруд"}},"決める":{"b":"決める (きめる)","p":"v","m":{"az":"qərar vermək, müəyyənləşdirmək","en":"to decide, to choose","ru":"решать, выбирать"},"n":{"az":"Nを決める nəyisə müəyyənləşdirmək, Nに決める isə N-i seçmək deməkdir; təsirsiz qarşılığı 決まる-dır.","en":"Nを決める means to decide something, Nに決める to choose N; the intransitive counterpart is 決まる.","ru":"Nを決める означает решить что-либо, Nに決める выбрать N; непереходная пара: 決まる."}},"泳ぐ":{"b":"泳ぐ (およぐ)","p":"v","m":{"az":"üzmək","en":"to swim","ru":"плавать"},"n":{"az":"泳ぎたくない - üzmək istəmirəm; 〜たい istək, 〜たくない isə inkar bildirir.","en":"泳ぎたくない means not wanting to swim; 〜たい expresses desire and 〜たくない negates it.","ru":"泳ぎたくない означает не хочу плавать; 〜たい выражает желание, а 〜たくない - отрицание."}},"泳げる":{"b":"泳げる (およげる)","p":"v","m":{"az":"üzə bilmək","en":"can swim","ru":"уметь плавать"},"n":{"az":"泳ぐ felinin potensial formasıdır; 泳げる qabiliyyəti bildirir və çox vaxt が ilə işlənir.","en":"Potential form of 泳ぐ; it expresses ability and commonly takes が.","ru":"Потенциальная форма 泳ぐ; выражает способность и часто употребляется с が."}},"漢字":{"b":"漢字 (かんじ)","p":"n","m":{"az":"kanci, yapon heroqlifləri","en":"kanji, Chinese characters used in Japanese","ru":"кандзи, иероглифы японского письма"}},"灰色":{"b":"灰色 (はいいろ)","p":"n","m":{"az":"boz rəng","en":"gray, grey","ru":"серый цвет"},"n":{"az":"灰色の + isim formasında işlənir: 灰色の猫 = boz pişik.","en":"Used as 灰色の + noun: 灰色の猫 = gray cat.","ru":"Используется как 灰色の + существительное: 灰色の猫 = серый кот."}},"牛乳":{"b":"牛乳 (ぎゅうにゅう)","p":"n","m":{"az":"inək südü","en":"cow's milk","ru":"коровье молоко"}},"猫":{"b":"猫 (ねこ)","p":"n","m":{"az":"pişik","en":"cat","ru":"кошка"}},"玄関":{"b":"玄関 (げんかん)","p":"n","m":{"az":"evin giriş hissəsi, dəhliz","en":"entrance hall, entryway","ru":"прихожая, входная зона"},"n":{"az":"Yapon evlərində ayaqqabının çıxarıldığı giriş yeridir.","en":"The entrance area of a Japanese home where shoes are removed.","ru":"Входная зона японского дома, где снимают обувь."}},"生まれる":{"b":"生まれる (うまれる)","p":"v","m":{"az":"doğulmaq","en":"to be born","ru":"рождаться"},"n":{"az":"生まれた keçmiş formadır; doğulduğu yer adətən 〜で göstərilir.","en":"生まれた is the past form; the birthplace is usually marked with で.","ru":"生まれた является прошедшей формой; место рождения обычно обозначается частицей で."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"白鳥":{"b":"白鳥 (はくちょう)","p":"n","m":{"az":"qu quşu","en":"swan","ru":"лебедь"}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"直す":{"b":"直す (なおす)","p":"v","m":{"az":"düzəltmək; təmir etmək","en":"to fix; to repair; to correct","ru":"чинить; исправлять"},"n":{"az":"Təsirli feldir, 直る isə düzəlməkdir; 書き直す yenidən yazmaq deməkdir.","en":"Transitive verb paired with 直る, to get fixed; 書き直す means to rewrite.","ru":"Переходный глагол, пара 直る означает исправляться; 書き直す означает переписывать."}},"眼鏡":{"b":"眼鏡 (めがね)","p":"n","m":{"az":"eynək","en":"glasses, spectacles","ru":"очки"},"n":{"az":"眼鏡を掛ける eynək taxmaq deməkdir.","en":"眼鏡を掛ける means to put on or wear glasses.","ru":"眼鏡を掛ける означает надевать или носить очки."}},"着く":{"b":"着く (つく)","p":"v","m":{"az":"çatmaq; yetişmək","en":"to arrive; to reach","ru":"прибывать; добираться"},"n":{"az":"Yerə çatmağı bildirir və adətən に ilə işlənir: 駅に着く.","en":"Indicates arrival at a place and usually takes に: 駅に着く.","ru":"Обозначает прибытие в место и обычно употребляется с に: 駅に着く."}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"笑い":{"b":"笑い (わらい)","p":"n","m":{"az":"gülüş, gülmə","en":"laughter, smile","ru":"смех, улыбка"},"n":{"az":"笑う felindən düzəlmiş isimdir; 笑い声 gülüş səsi deməkdir.","en":"A noun derived from 笑う; 笑い声 means the sound of laughter.","ru":"Существительное от 笑う; 笑い声 означает звук смеха."}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"笑顔":{"b":"笑顔 (えがお)","p":"n","m":{"az":"təbəssüm, gülər üz","en":"smile, smiling face","ru":"улыбка, улыбающееся лицо"}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"絵":{"b":"絵 (え)","p":"n","m":{"az":"şəkil, rəsm","en":"picture, drawing","ru":"картина, рисунок"}},"続ける":{"b":"続ける (つづける)","p":"v","m":{"az":"davam etdirmək","en":"to continue, to keep doing","ru":"продолжать"},"n":{"az":"続ける təsirli feildir, 続く isə bir şeyin davam etməsini bildirir.","en":"続ける is transitive, while 続く means something continues.","ru":"続ける переходный глагол, а 続く означает продолжаться."}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"美しい":{"b":"美しい (うつくしい)","p":"ai","m":{"az":"gözəl; füsunkar","en":"beautiful; lovely","ru":"красивый; прекрасный"},"n":{"az":"い-sifətdir; mənfi forması 美しくない olur.","en":"An i-adjective; its negative form is 美しくない.","ru":"Это прилагательное на い; отрицательная форма 美しくない."}},"羽":{"b":"羽 (はね)","p":"n","m":{"az":"lələk; qanad","en":"feather; wing","ru":"перо; крыло"},"n":{"az":"İsim kimi はね oxunur; quş sayğacı kimi 羽 (わ) işlənir.","en":"As a noun it is はね; as a bird counter it is 羽 (わ).","ru":"Как существительное читается はね; как счётное слово для птиц читается わ."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"肩":{"b":"肩 (かた)","p":"n","m":{"az":"çiyin","en":"shoulder","ru":"плечо"}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"袋":{"b":"袋 (ふくろ)","p":"n","m":{"az":"torba, paket","en":"bag, sack","ru":"пакет, мешок"}},"見つかる":{"b":"見つかる (みつかる)","p":"v","m":{"az":"tapılmaq; aşkar olunmaq","en":"to be found; to be discovered","ru":"находиться; обнаруживаться"},"n":{"az":"Təsirsiz feldir, 見つける isə tapmaqdır; 見つからないで tapılmadan deməkdir.","en":"Intransitive verb paired with 見つける, to find; 見つからないで means without being found.","ru":"Непереходный глагол, пара 見つける означает находить; 見つからないで значит не будучи найденным."}},"見つける":{"b":"見つける (みつける)","p":"v","m":{"az":"tapmaq; aşkar etmək","en":"find; discover","ru":"находить; обнаруживать"},"n":{"az":"Təsirli feldir; 見つかる tapılmaq deməkdir.","en":"A transitive verb; 見つかる means to be found.","ru":"Переходный глагол; 見つかる означает найтись."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"覚える":{"b":"覚える (おぼえる)","p":"v","m":{"az":"yadda saxlamaq; öyrənmək","en":"to memorize; to remember","ru":"запоминать; заучивать"},"n":{"az":"覚えました öyrəndim və ya yadda saxladım deməkdir.","en":"覚えました means memorized or learned.","ru":"覚えました означает запомнил или выучил."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"言葉":{"b":"言葉 (ことば)","p":"n","m":{"az":"söz, dil, ifadə","en":"word, language, expression","ru":"слово, язык, выражение"},"n":{"az":"日本語の言葉 = yapon sözü; 優しい言葉 = mehriban sözlər.","en":"日本語の言葉 = Japanese word; 優しい言葉 = kind words.","ru":"日本語の言葉 = японское слово; 優しい言葉 = добрые слова."}},"話せる":{"b":"話せる (はなせる)","p":"v","m":{"az":"danışa bilmək","en":"to be able to speak","ru":"уметь говорить"},"n":{"az":"話す felinin potensial formasıdır; 話せませんでした keçmişdə danışa bilmədi deməkdir.","en":"Potential form of 話す; 話せませんでした means could not speak.","ru":"Потенциальная форма 話す; 話せませんでした означает не мог говорить."}},"語":{"b":"語 (ご)","p":"n","m":{"az":"dil, söz","en":"language, word","ru":"язык, слово"},"n":{"az":"Dil adlarında şəkilçi kimi işlənir: 日本語 yapon dili, 英語 ingilis dili.","en":"It forms language names: 日本語 Japanese, 英語 English.","ru":"Используется в названиях языков: 日本語 японский, 英語 английский."}},"説明":{"b":"説明 (せつめい)","p":"n","m":{"az":"izah; açıqlama","en":"explanation; description","ru":"объяснение; разъяснение"},"n":{"az":"説明する izah etmək, 説明してください isə zəhmət olmasa izah edin deməkdir.","en":"説明する means to explain, and 説明してください means please explain.","ru":"説明する означает объяснять, а 説明してください означает пожалуйста, объясните."}},"読める":{"b":"読む (よむ)","p":"v","m":{"az":"oxuya bilmək","en":"to be able to read","ru":"уметь читать; мочь прочитать"},"n":{"az":"読める, 読む felinin potensial formasıdır; 読めました nəzakətli keçmiş formadır.","en":"読める is the potential form of 読む; 読めました is its polite past form.","ru":"読める является формой возможности глагола 読む; 読めました является вежливой прошедшей формой."}},"誰":{"b":"誰 (だれ)","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"誰が = kim, 誰に = kimə, 誰の = kimin.","en":"誰が = who as subject; 誰に = to whom; 誰の = whose.","ru":"誰が = кто; 誰に = кому; 誰の = чей."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"買い物":{"b":"買い物 (かいもの)","p":"n","m":{"az":"alış-veriş","en":"shopping","ru":"покупки, шопинг"},"n":{"az":"買い物をする = alış-veriş etmək; 買い物に行く = alış-verişə getmək.","en":"買い物をする = to shop; 買い物に行く = to go shopping.","ru":"買い物をする = делать покупки; 買い物に行く = идти за покупками."}},"買う":{"b":"買う (かう)","p":"v","m":{"az":"almaq; satın almaq","en":"buy","ru":"покупать"},"n":{"az":"て forması 買って olur.","en":"Its て-form is 買って.","ru":"Форма на て: 買って."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"連れる":{"b":"連れる (つれる)","p":"v","m":{"az":"özü ilə aparmaq, müşayiət etmək","en":"to take along, to accompany","ru":"брать с собой, вести"},"n":{"az":"連れて行く birini aparmaq, 連れて来る isə birini gətirmək deməkdir.","en":"連れて行く means to take someone along; 連れて来る means to bring someone.","ru":"連れて行く означает взять кого-то с собой, а 連れて来る означает привести кого-то."}},"運転":{"b":"運転 (うんてん)","p":"n","m":{"az":"nəqliyyat vasitəsini idarə etmə","en":"driving","ru":"вождение"},"n":{"az":"運転する nəqliyyat vasitəsini idarə etmək deməkdir.","en":"運転する means to drive a vehicle.","ru":"運転する означает управлять транспортным средством."}},"遠く":{"b":"遠く (とおく)","p":"n","m":{"az":"uzaq yer, uzaqlıq","en":"faraway place, distance","ru":"далёкое место, даль"},"n":{"az":"遠い sifətinin formasıdır; 遠くに uzaqda deməkdir.","en":"Derived from 遠い; 遠くに means far away.","ru":"Образовано от 遠い; 遠くに означает далеко."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"閉じる":{"b":"閉じる (とじる)","p":"v","m":{"az":"bağlamaq; bağlanmaq","en":"to close; to shut","ru":"закрывать; закрываться"},"n":{"az":"Həm təsirli, həm təsirsizdir: 本を閉じる = kitabı bağlamaq, 店が閉じる = mağazanın bağlanması.","en":"Can be transitive or intransitive: 本を閉じる = close a book, 店が閉じる = a shop closes.","ru":"Бывает переходным и непереходным: 本を閉じる = закрыть книгу, 店が閉じる = магазин закрывается."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"間":{"b":"間 (あいだ)","p":"n","m":{"az":"ara, aralıq, müddət","en":"between, interval, duration","ru":"между, промежуток, время"},"n":{"az":"AとBの間 iki şeyin arasını, 〜の間 isə müddəti bildirir.","en":"AとBの間 means between A and B, while 〜の間 can indicate duration.","ru":"AとBの間 означает между A и B, а 〜の間 может обозначать промежуток времени."}},"雪":{"b":"雪 (ゆき)","p":"n","m":{"az":"qar","en":"snow","ru":"снег"}},"震える":{"b":"震える (ふるえる)","p":"v","m":{"az":"titrəmək; əsmək","en":"to tremble; to shiver","ru":"дрожать; трястись"},"n":{"az":"Soyuqdan və ya qorxudan titrəmək üçün işlənir.","en":"Used for trembling from cold or fear.","ru":"Используется для дрожи от холода или страха."}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"飛べる":{"b":"飛べる (とべる)","p":"v","m":{"az":"uça bilmək","en":"to be able to fly","ru":"уметь летать; мочь летать"},"n":{"az":"飛ぶ feilinin potensial formasıdır; 飛べませんでした uça bilmədi deməkdir.","en":"The potential form of 飛ぶ; 飛べませんでした means could not fly.","ru":"Потенциальная форма 飛ぶ; 飛べませんでした означает не смог летать."}},"食べ物":{"b":"食べ物 (たべもの)","p":"n","m":{"az":"yemək; qida","en":"food; something to eat","ru":"еда; пища"}},"高い":{"b":"高い (たかい)","p":"ai","m":{"az":"hündür; baha","en":"high; expensive","ru":"высокий; дорогой"},"n":{"az":"い-sifətdir; 高かった keçmiş formadır.","en":"It is an i-adjective; 高かった is its past form.","ru":"Это i-прилагательное; 高かった - форма прошедшего времени."}},"髪":{"b":"髪 (かみ)","p":"n","m":{"az":"saç","en":"hair","ru":"волосы"}},"魔法":{"b":"魔法 (まほう)","p":"n","m":{"az":"sehr, sehrbazlıq","en":"magic, sorcery","ru":"магия, волшебство"},"n":{"az":"魔法を使う = sehr işlətmək.","en":"魔法を使う = to use magic or cast a spell.","ru":"魔法を使う = использовать магию или колдовать."}},"魚":{"b":"魚 (さかな)","p":"n","m":{"az":"balıq","en":"fish","ru":"рыба"}},"鳥":{"b":"鳥 (とり)","p":"n","m":{"az":"quş","en":"bird","ru":"птица"}}}};